// ====== EDIT ME ======
return [{ json: {
  // mode: "mock"   = no API key; summary is written by fixed rules from the numbers (still useful)
  //       "gemini" = AI-written summary with your own Gemini API key (credential "Gemini API Key")
  mode: "mock",
  // source: "sample" = built-in FAKE shop data, to test the install
  //         "files"  = Etsy CSVs you put in filesFolder (self-hosted n8n only)
  //         "sheet"  = tabs Statement / OrderItems / COGS in your Google Sheet
  source: "sample",
  // output: "files" = 3 CSV files in outputFolder (self-hosted only); "sheet" = tabs P&L / By Listing / Summary
  output: "files",
  filesFolder: "/home/node/.n8n-files/etsy-profit",
  outputFolder: "/home/node/.n8n-files",
  currency: "",            // leave empty = take it from the statement (e.g. USD, EUR, GBP)
  dateOrder: "MDY",         // how to read dates like 03/09/26 in the Order Items CSV: "MDY" (US Etsy export) or "DMY"
  monthlyOtherCosts: 0,    // costs Etsy doesn't know about, per month (packaging bulk buys, software...)
  lowMarginPct: 15,        // listings under this margin get flagged LOW_MARGIN
  summaryLanguage: "en",      // en, zh, de, fr, es, ja
  geminiModel: "gemini-flash-latest",   // Google's alias for the current Flash model; older names (e.g. gemini-2.5-flash) can return 404 for new keys. Any Flash model listed in Google AI Studio works.
}}];

// Collect the three inputs into one item. Rows from nodes that did not run (or files that were missing) are simply empty.
const cfg = $('Config').first().json;
const grab = n => { try { return $(n).isExecuted ? $(n).all().map(i => i.json) : []; } catch (e) { return []; } };
const N = cfg.source === 'sheet' ? ['Read Statement tab', 'Read OrderItems tab', 'Read COGS tab'] : ['Parse statement CSV', 'Parse Order Items CSV', 'Parse COGS CSV'];
return [{ json: { statement: grab(N[0]), orderItems: grab(N[1]), cogs: grab(N[2]) } }];

// ===== Compute P&L (pure math, no AI) =====
// Input: one item { statement:[rows], orderItems:[rows], cogs:[rows] } with Etsy's own column names.
// Buyer names / addresses are never copied: only money, dates, IDs, item names and SKUs are read.
const cfg = $('Config').first().json;
const src = $input.first().json || {};
const R = n => Math.round((Number(n) || 0) * 100) / 100;
const issues = [];
const issue = (check, detail) => issues.push({ check, detail: String(detail).slice(0, 300) });

const normKey = k => String(k ?? '').replace(/^\uFEFF/, '').replace(/\s+/g, ' ').trim().toLowerCase();
const normRow = r => { const o = {}; for (const [k, v] of Object.entries(r || {})) o[normKey(k)] = v; return o; };
const get = (o, names) => { for (const n of names) { const v = o[n]; if (v !== undefined && v !== null && String(v).trim() !== '') return v; } return ''; };

// "$1,234.56" "-€0.20" "€3,99" "(1.00)" "--" 12.5  -> number (0 for "--"/empty), null if unreadable
function money(v) {
  if (typeof v === 'number') return isFinite(v) ? v : null;
  const s = String(v ?? '').trim();
  if (!s || /^[-–—]{1,2}$/.test(s)) return 0;
  const neg = /^\(.*\)$/.test(s) || /^[^\d]*[-−–]/.test(s) || /[-−]\s*$/.test(s);
  const num = s.replace(/[^\d.,]/g, '');
  if (!/\d/.test(num)) return null;
  const lc = num.lastIndexOf(','), ld = num.lastIndexOf('.');
  let dec = '.';
  if (lc > -1 && ld > -1) dec = lc > ld ? ',' : '.';
  else if (lc > -1) dec = /,\d{1,2}$/.test(num) ? ',' : 'none';
  const clean = dec === ',' ? num.replace(/\./g, '').replace(',', '.') : num.replace(/,/g, '');
  const n = parseFloat(clean);
  return isFinite(n) ? (neg ? -n : n) : null;
}

const MON = { jan: 1, feb: 2, mar: 3, 'mär': 3, apr: 4, may: 5, mai: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, okt: 10, nov: 11, dec: 12, dez: 12 };
const ym = (y, m) => (y > 1900 && m >= 1 && m <= 12) ? `${y}-${String(m).padStart(2, '0')}` : null;
// "August 3, 2026" "26. February 2026" "08/03/26" "2026-08-03" Sheets serial -> "2026-08"
function monthOf(v) {
  if (v === '' || v === null || v === undefined) return null;
  if (typeof v === 'number') { const d = new Date(Math.round((v - 25569) * 86400000)); return ym(d.getUTCFullYear(), d.getUTCMonth() + 1); }
  const s = String(v).trim();
  let m = s.match(/(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return ym(+m[1], +m[2]);
  const w = s.toLowerCase().match(/[a-zäéû]{3,}/);
  if (w && MON[w[0].slice(0, 3)]) {
    const y4 = s.match(/\b(\d{4})\b/), y2 = s.match(/\b(\d{2})\s*$/);
    const y = y4 ? +y4[1] : (y2 ? 2000 + +y2[1] : 0);
    return ym(y, MON[w[0].slice(0, 3)]);
  }
  m = s.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})/);
  if (m) {
    let a = +m[1], b = +m[2], y = +m[3]; if (y < 100) y += 2000;
    const month = (cfg.dateOrder === 'DMY' || a > 12) ? b : a;
    return ym(y, month);
  }
  return null;
}

// ---- statement rows -> categories ----
function category(type, title) {
  const t = normKey(type), x = normKey(title);
  if (/deposit|überweisung|auszahlung|virement|depósito/.test(t) || /sent to your bank|bankkonto überwiesen/.test(x)) return 'transfer';
  if (t === 'payment' || t === 'zahlung') return 'transfer';
  if (t === 'sale' || t === 'verkauf') return 'sales';
  if (t === 'refund' || t === 'erstattung' || t === 'rückerstattung') return 'refunds';
  if (['tax', 'vat', 'gst', 'steuer', 'ust'].includes(t)) return 'taxes';
  if (/offsite|off-site/.test(x)) return 'offsite_ads';
  if (/transaction fee|transaktionsgebühr/.test(x)) return 'transaction_fees';
  if (/processing fee|zahlungsbearbeitung|payment processing/.test(x)) return 'processing_fees';
  if (/listing fee|einstellgebühr|renew/.test(x) || t === 'listing') return 'listing_fees';
  if (t === 'marketing' || /etsy ads|promoted listing/.test(x)) return 'etsy_ads';
  if (t === 'shipping' || /shipping label|postage label|versandetikett/.test(x)) return 'shipping_labels';
  if (t === 'subscription' || /subscription|etsy plus|abonnement/.test(x)) return 'subscription';
  if (/\b(vat|gst|hst|sales tax|ust|mwst)\b/.test(x)) return 'taxes';
  if (['fee', 'transaction', 'gebühr'].includes(t) || /fee|gebühr/.test(x)) return 'other_fees';
  return 'unknown';
}
const orderIdOf = s => { const m = String(s || '').match(/(?:order|bestellung|commande|pedido)\s*#?\s*(\d{5,})/i); return m ? m[1] : null; };
const listingIdOf = s => { const m = String(s || '').match(/(?:listing|artikel|annonce|anuncio)\s*#?\s*(\d{5,})/i); return m ? m[1] : null; };

const H = { date: ['date', 'datum', 'fecha'], type: ['type', 'art', 'tipo'], title: ['title', 'titel', 'título', 'titre', 'description'],
  info: ['info'], currency: ['currency', 'währung', 'moneda', 'devise'], amount: ['amount', 'betrag', 'importe', 'montant'],
  fees: ['fees & taxes', 'gebühren & steuern', 'fees and taxes'], net: ['net', 'netto', 'neto'] };

let stmt = [];
for (const raw of (src.statement || [])) {
  const r = normRow(raw);
  const type = String(get(r, H.type)).trim(), title = String(get(r, H.title)).trim(), info = String(get(r, H.info)).trim();
  if (!type && !title) continue;
  const cat = category(type, title);
  if (cat === 'transfer') continue;                      // deposits/payments move cash, they are not profit or loss
  const month = monthOf(get(r, H.date));
  if (!month) { issue('UNPARSED_DATE', `Statement row "${type} ${title.slice(0, 50)}" date "${get(r, H.date)}" skipped`); continue; }
  const net = money(get(r, H.net)), amountRaw = money(get(r, H.amount));
  if (net === null) { issue('UNPARSED_AMOUNT', `Statement row "${type} ${title.slice(0, 50)}" net "${get(r, H.net)}" skipped`); continue; }
  stmt.push({ month, type, title, info, cat, net, amount: amountRaw || net, currency: String(get(r, H.currency)).trim().toUpperCase(),
    orderId: orderIdOf(title + ' ' + info), listingId: listingIdOf(info) });
}
// currency: one shop currency only
const curCount = {};
stmt.forEach(s => { if (s.currency) curCount[s.currency] = (curCount[s.currency] || 0) + 1; });
const cur = String(cfg.currency || Object.entries(curCount).sort((a, b) => b[1] - a[1])[0]?.[0] || '').toUpperCase();
const badCur = stmt.filter(s => s.currency && cur && s.currency !== cur);
if (badCur.length) issue('CURRENCY_MISMATCH', `${badCur.length} statement row(s) not in ${cur} were skipped (${[...new Set(badCur.map(s => s.currency))].join(', ')})`);
stmt = stmt.filter(s => !(s.currency && cur && s.currency !== cur));
stmt.filter(s => s.cat === 'unknown').forEach(s => issue('UNKNOWN_ROW_TYPE', `${s.month} "${s.type}: ${s.title.slice(0, 60)}" ${R(s.net)} counted in "other"`));

const months = [...new Set(stmt.map(s => s.month))].sort();
const monthSet = new Set(months);
if (!months.length) issue('NO_STATEMENT_ROWS', 'No usable rows in the Etsy monthly statement CSV. Check the file/tab name and that it is the "Monthly statement" CSV, not the Orders CSV.');

// ---- COGS table ----
const cogsBy = { sku: {}, lid: {}, name: [] };
for (const raw of (src.cogs || [])) {
  const r = normRow(raw);
  const unit = money(get(r, ['unit_cost', 'unit cost', 'cost', 'cogs']));
  if (unit === null || get(r, ['unit_cost', 'unit cost', 'cost', 'cogs']) === '') continue;
  const extra = money(get(r, ['extra_cost_per_unit', 'extra cost per unit', 'packaging_cost', 'shipping_cost'])) || 0;
  const c = { unit: Math.abs(unit), extra: Math.abs(extra) };
  const sku = normKey(get(r, ['sku'])), lid = String(get(r, ['listing_id', 'listing id'])).trim(), name = normKey(get(r, ['item_name', 'item name', 'listing', 'title']));
  if (sku) cogsBy.sku[sku] = c;
  if (lid) cogsBy.lid[lid] = c;
  if (name) cogsBy.name.push([name, c]);
}
const costFor = (sku, lid, name) => cogsBy.sku[normKey(sku)] || cogsBy.lid[String(lid)] ||
  (cogsBy.name.find(([n]) => n === normKey(name)) || cogsBy.name.find(([n]) => normKey(name).startsWith(n) || n.startsWith(normKey(name))) || [])[1] || null;

// ---- order items -> listing lines ----
const OI = { date: ['sale date', 'date paid'], name: ['item name', 'title'], qty: ['quantity'], price: ['price'], total: ['item total'],
  ship: ['order shipping'], order: ['order id'], lid: ['listing id'], sku: ['sku'], currency: ['currency'] };
const L = {}, orders = {};
let outside = 0, itemCurBad = 0;
const items = [];
for (const raw of (src.orderItems || [])) {
  const r = normRow(raw);
  const name = String(get(r, OI.name)).trim(), oid = String(get(r, OI.order)).trim().replace(/\.0+$/, '');
  if (!name && !oid) continue;
  const month = monthOf(get(r, OI.date));
  if (!month) { issue('UNPARSED_DATE', `Order item "${name.slice(0, 50)}" date "${get(r, OI.date)}" skipped`); continue; }
  if (months.length && !monthSet.has(month)) { outside++; continue; }
  const c = String(get(r, OI.currency)).trim().toUpperCase();
  if (c && cur && c !== cur) { itemCurBad++; continue; }
  const qty = Math.abs(money(get(r, OI.qty)) || 1);
  const price = money(get(r, OI.price)) || 0;
  items.push({ r, name, oid, month, qty, revenue: money(get(r, OI.total)) || price * qty,
    lid: String(get(r, OI.lid)).trim().replace(/\.0+$/, ''), sku: String(get(r, OI.sku)).trim(), ship: money(get(r, OI.ship)) || 0 });
}
// Only count items whose order has a Sale row in the statement (profit is counted when Etsy paid you).
const saleOrderIds = new Set(stmt.filter(s => s.cat === 'sales' && s.orderId).map(s => s.orderId));
const canMatch = saleOrderIds.size > 0;
if (!canMatch && items.length && stmt.some(s => s.cat === 'sales')) issue('ORDER_IDS_NOT_FOUND', 'Could not read order numbers from the statement Sale rows, so orders were not matched one by one; per-listing fee split is less precise.');
const notPaid = {};
for (const it of items) {
  if (canMatch && it.oid && !saleOrderIds.has(it.oid)) { const n = notPaid[it.oid] ||= { month: it.month, total: it.ship }; n.total += it.revenue; continue; }
  const key = `${it.month}|${it.lid || it.sku || normKey(it.name)}`;
  const line = L[key] ||= { month: it.month, listing: it.name.slice(0, 100), sku: it.sku, listing_id: it.lid, units: 0, revenue: 0, shipping_income: 0, refunds: 0,
    etsy_fees: 0, ads: 0, shipping_labels: 0, taxes: 0, other: 0, sale_adjustment: 0, cogs: 0, missing_cogs: false };
  const cost = costFor(it.sku, it.lid, it.name);
  if (!cost) line.missing_cogs = true;
  line.units += it.qty; line.revenue += it.revenue; line.cogs += cost ? it.qty * (cost.unit + cost.extra) : 0;
  const o = orders[it.oid || ('noid-' + key)] ||= { month: it.month, lines: [], ship: it.ship, saleAmount: null };
  o.lines.push({ key, name: normKey(it.name), rev: it.revenue });
}
Object.entries(notPaid).forEach(([oid, n]) => issue('ORDER_NOT_IN_STATEMENT', `Order #${oid} (${n.month}, items total ${R(n.total)}) is in Order Items but has no Sale row in the statement (paid next month or cancelled?); left out of profit and cost of goods`));
if (outside) issue('ORDER_ITEMS_OUTSIDE_STATEMENT_MONTHS', `${outside} order item row(s) are from months the statement does not cover (statement covers: ${months.join(', ') || 'none'}) and were left out`);
if (itemCurBad) issue('CURRENCY_MISMATCH', `${itemCurBad} order item rows not in ${cur} were skipped`);
if (!Object.keys(orders).length && months.length) issue('NO_ORDER_ITEMS', 'No Order Items rows for these months: per-listing profit and cost of goods are missing, so net profit is overstated.');

// shipping charged to buyers: once per order, split by item revenue
const share = (o, amount, bucket) => {
  const tot = o.lines.reduce((a, l) => a + l.rev, 0);
  o.lines.forEach(l => { L[l.key][bucket] += amount * (tot ? l.rev / tot : 1 / o.lines.length); });
};
Object.values(orders).forEach(o => share(o, o.ship, 'shipping_income'));

// ---- allocate statement rows to listing lines; the rest is shop-level ----
const shop = {};
const shopOf = m => shop[m] ||= { month: m, listing: '(Shop-level: not tied to a listing)', sku: '', listing_id: '', units: 0, revenue: 0, shipping_income: 0,
  refunds: 0, etsy_fees: 0, ads: 0, shipping_labels: 0, taxes: 0, other: 0, sale_adjustment: 0, cogs: 0, missing_cogs: false };
const BUCKET = { refunds: 'refunds', transaction_fees: 'etsy_fees', processing_fees: 'etsy_fees', listing_fees: 'etsy_fees', other_fees: 'etsy_fees',
  subscription: 'etsy_fees', offsite_ads: 'ads', etsy_ads: 'ads', shipping_labels: 'shipping_labels', taxes: 'taxes', unknown: 'other' };
const linesInMonth = m => Object.entries(L).filter(([k]) => k.startsWith(m + '|'));
for (const s of stmt) {
  const o = s.orderId ? orders[s.orderId] : null;
  if (s.cat === 'sales') {
    if (o) { o.saleAmount = (o.saleAmount || 0) + s.amount; if (s.net !== s.amount) share(o, s.net - s.amount, 'etsy_fees'); }
    else if (!canMatch && items.length) { const sh = shopOf(s.month); sh.sale_adjustment += s.amount; sh.etsy_fees += s.net - s.amount; }
    else { const sh = shopOf(s.month); sh.revenue += s.amount; sh.etsy_fees += s.net - s.amount;
      issue('SALE_WITHOUT_ORDER_ITEMS', `${s.month} ${s.title.slice(0, 60)} (${R(s.amount)}) has no row in the Order Items CSV: no cost of goods counted for it`); }
    continue;
  }
  const bucket = BUCKET[s.cat];
  if (o) {
    const after = normKey(s.title.split(':').slice(1).join(':'));
    const hit = s.cat === 'transaction_fees' && after && o.lines.find(l => l.name && (l.name.startsWith(after) || after.startsWith(l.name)));
    if (hit) L[hit.key][bucket] += s.net; else share(o, s.net, bucket);
    continue;
  }
  if (s.listingId) {
    const hit = linesInMonth(s.month).find(([, l]) => l.listing_id === s.listingId);
    if (hit) { hit[1][bucket] += s.net; continue; }
  }
  if (s.cat === 'transaction_fees') {
    const after = normKey(s.title.split(':').slice(1).join(':'));
    const hit = after && linesInMonth(s.month).find(([, l]) => normKey(l.listing).startsWith(after) || after.startsWith(normKey(l.listing)));
    if (hit) { hit[1][bucket] += s.net; continue; }
  }
  shopOf(s.month)[bucket] += s.net;
}
// reconciliation: statement sale vs order items (items + shipping)
for (const [oid, o] of Object.entries(orders)) {
  const itemsTotal = o.lines.reduce((a, l) => a + l.rev, 0) + o.ship;
  if (o.saleAmount === null || oid.startsWith('noid-')) continue;
  const diff = o.saleAmount - itemsTotal;
  if (Math.abs(diff) >= 0.005) share(o, diff, 'sale_adjustment');
  if (Math.abs(o.saleAmount - itemsTotal) > Math.max(0.05, itemsTotal * 0.01)) issue('ORDER_TOTAL_DIFF', `Order #${oid}: statement ${R(o.saleAmount)} vs Order Items ${R(itemsTotal)} (discount, sales tax or edited order?); difference booked in sale_adjustment`);
}

if (!canMatch) {  // order ids unreadable: settle statement sales vs Order Items per month at shop level
  for (const m of months) { const sh = shopOf(m);
    sh.sale_adjustment -= Object.values(orders).filter(o => o.month === m).reduce((a, o) => a + o.ship + o.lines.reduce((b, l) => b + l.rev, 0), 0);
    if (Math.abs(sh.sale_adjustment) < 0.005) sh.sale_adjustment = 0; }
}
// monthlyOtherCosts sit in the shop-level row so the listing rows add up to net profit
const otherCostsCfg = Math.abs(Number(cfg.monthlyOtherCosts) || 0);
if (otherCostsCfg) months.forEach(m => { shopOf(m).other -= otherCostsCfg; });

// ---- monthly P&L from the statement (the authoritative numbers) ----
const CATS = ['transaction_fees', 'processing_fees', 'listing_fees', 'etsy_ads', 'offsite_ads', 'shipping_labels', 'taxes', 'subscription', 'other_fees', 'unknown'];
const otherCosts = Math.abs(Number(cfg.monthlyOtherCosts) || 0);
const lineRows = Object.values(L);
const monthly = months.map(m => {
  const rows = stmt.filter(s => s.month === m), sum = f => rows.filter(f).reduce((a, s) => a + s.net, 0);
  const sales = rows.filter(s => s.cat === 'sales');
  const o = { month: m, currency: cur,
    orders: new Set(sales.map(s => s.orderId || s.title)).size,
    units: lineRows.filter(l => l.month === m).reduce((a, l) => a + l.units, 0),
    gross_sales: R(sales.reduce((a, s) => a + s.amount, 0)),
    fees_taxes_in_sale_rows: R(sales.reduce((a, s) => a + (s.net - s.amount), 0)),
    refunds: R(sum(s => s.cat === 'refunds')) };
  CATS.forEach(c => { o[c === 'unknown' ? 'other' : c] = R(sum(s => s.cat === c)); });
  o.etsy_net = R(rows.reduce((a, s) => a + s.net, 0));
  o.cogs = R(lineRows.filter(l => l.month === m).reduce((a, l) => a + l.cogs, 0));
  o.other_costs = R(otherCosts);
  o.net_profit = R(o.etsy_net - o.cogs - o.other_costs);
  o.margin_pct = o.gross_sales ? R(o.net_profit / o.gross_sales * 100) : '';
  const feeTotal = o.fees_taxes_in_sale_rows + o.transaction_fees + o.processing_fees + o.listing_fees + o.etsy_ads + o.offsite_ads + o.subscription + o.other_fees;
  o.etsy_fees_and_ads_pct = o.gross_sales ? R(-feeTotal / o.gross_sales * 100) : '';
  const parts = o.gross_sales + o.fees_taxes_in_sale_rows + o.refunds + CATS.reduce((a, c) => a + o[c === 'unknown' ? 'other' : c], 0);
  if (Math.abs(parts - o.etsy_net) > 0.02) issue('INTERNAL_SUM_CHECK', `${m}: categories add up to ${R(parts)} but statement net is ${o.etsy_net}`);
  return o;
});

// ---- per-listing rows ----
const lowPct = Number(cfg.lowMarginPct ?? 15);
const fin = l => {
  const income = l.revenue + l.shipping_income;
  const profit = income + l.sale_adjustment + l.refunds + l.etsy_fees + l.ads + l.shipping_labels + l.taxes + l.other - l.cogs;
  const flags = [];
  if (l.missing_cogs) flags.push('MISSING_COGS');
  if (l.refunds < 0) flags.push('REFUNDED');
  if (l.units && profit < 0) flags.push('LOSS');
  else if (l.units && income > 0 && profit / income * 100 < lowPct) flags.push('LOW_MARGIN');
  return { month: l.month, listing: l.listing, sku: l.sku, listing_id: l.listing_id, units: l.units, revenue: R(l.revenue),
    shipping_income: R(l.shipping_income), sale_adjustment: R(l.sale_adjustment), refunds: R(l.refunds), etsy_fees: R(l.etsy_fees), ads: R(l.ads), shipping_labels: R(l.shipping_labels),
    taxes: R(l.taxes), other: R(l.other), cogs: R(l.cogs), profit: R(profit), margin_pct: income ? R(profit / income * 100) : '',
    profit_per_unit: l.units ? R(profit / l.units) : '', flags: flags.join('; ') };
};
const listings = [...lineRows.map(fin).sort((a, b) => a.month.localeCompare(b.month) || a.profit - b.profit),
  ...months.filter(m => shop[m]).map(m => fin(shop[m]))].sort((a, b) => a.month.localeCompare(b.month));
monthly.forEach(mo => { const t = listings.filter(l => l.month === mo.month).reduce((a, l) => a + l.profit, 0);
  if (Math.abs(t - mo.net_profit) > 0.02 * Math.max(1, listings.filter(l => l.month === mo.month).length)) issue('LISTING_SUM_CHECK', `${mo.month}: listing rows add up to ${R(t)} but net profit is ${mo.net_profit}`); });
listings.filter(l => l.flags.includes('MISSING_COGS')).forEach(l => issue('MISSING_COGS', `${l.month} "${l.listing.slice(0, 60)}" (SKU ${l.sku || '-'}) has no cost in the COGS table: counted as 0, profit overstated`));

// ---- rule-based summary (always produced; used as-is in mock mode or if the AI call fails) ----
const SYM = { USD: '$', EUR: '€', GBP: '£', CAD: 'CA$', AUD: 'A$', JPY: '¥' };
const fmt = n => (n < 0 ? '-' : '') + (SYM[cur] || '') + Math.abs(n).toFixed(2) + (SYM[cur] ? '' : ' ' + cur);
const latest = months[months.length - 1], prev = months[months.length - 2];
const ML = monthly.find(m => m.month === latest), MP = monthly.find(m => m.month === prev);
const inLatest = listings.filter(l => l.month === latest && l.units);
const losers = inLatest.filter(l => l.flags.includes('LOSS')).sort((a, b) => a.profit - b.profit).slice(0, 5);
const lowM = inLatest.filter(l => l.flags.includes('LOW_MARGIN')).slice(0, 5);
const best = [...inLatest].sort((a, b) => b.profit - a.profit).slice(0, 3);
const missing = [...new Set(listings.filter(l => l.flags.includes('MISSING_COGS')).map(l => l.listing))];
const driver = l => {
  const d = [['cost of goods', 'cogs', l.cogs], ['shipping labels', 'shipping labels', -l.shipping_labels], ['Etsy fees', 'etsy_fees', -l.etsy_fees], ['ads', 'ads', -l.ads], ['refunds', 'refunds', -l.refunds]].sort((a, b) => b[2] - a[2])[0];
  return d;
};
const ZH = { 'cost of goods': '商品成本', 'shipping labels': '运费标签', 'Etsy fees': 'Etsy 手续费', ads: '广告费', refunds: '退款' };
const sh = shop[latest] || {};
const checkCounts = Object.entries(issues.reduce((a, i) => (a[i.check] = (a[i.check] || 0) + 1, a), {})).map(([k, v]) => `${k} ×${v}`).join(', ');
let en = [], zh = [];
if (!ML) { en.push('No statement data found, so no profit could be calculated.'); zh.push('没有读到结算单数据，无法计算利润。'); }
else {
  const incL = inLatest.reduce((a, l) => a + l.revenue + l.shipping_income, 0), incMiss = inLatest.filter(l => l.flags.includes('MISSING_COGS')).reduce((a, l) => a + l.revenue + l.shipping_income, 0);
  if (incL > 0 && incMiss / incL > 0.5) { en.push(`Warning: listings with no cost entered make up ${R(incMiss / incL * 100)}% of ${latest} sales, so the profit and margin below are too high. Fill in the COGS table first.`); zh.push(`注意：${latest} 有 ${R(incMiss / incL * 100)}% 的销售额来自没填成本的 listing，下面的利润和利润率偏高，请先补全 COGS 表。`); }
  en.push(`${latest}: net profit ${fmt(ML.net_profit)} on ${fmt(ML.gross_sales)} gross sales (margin ${ML.margin_pct}%). Etsy fees and ads took ${ML.etsy_fees_and_ads_pct}% of sales.` + (MP ? ` Previous month (${prev}): ${fmt(MP.net_profit)}.` : ''));
  zh.push(`${latest}：净利润 ${fmt(ML.net_profit)}，销售额 ${fmt(ML.gross_sales)}，利润率 ${ML.margin_pct}%；Etsy 手续费和广告占销售额 ${ML.etsy_fees_and_ads_pct}%。` + (MP ? `上月（${prev}）净利润 ${fmt(MP.net_profit)}。` : ''));
  if (losers.length) {
    en.push('Lost money: ' + losers.map(l => { const d = driver(l); return `${l.listing} (${fmt(l.profit)}; biggest cost: ${d[0]} ${fmt(d[2])})`; }).join('; ') + '.');
    zh.push('亏钱的 listing：' + losers.map(l => { const d = driver(l); return `${l.listing}（${fmt(l.profit)}，最大成本：${ZH[d[0]]} ${fmt(d[2])}）`; }).join('；') + '。');
  } else { en.push(`No listing lost money in ${latest}.`); zh.push(`${latest} 没有亏钱的 listing。`); }
  if (lowM.length) { en.push(`Margin under ${lowPct}%: ` + lowM.map(l => `${l.listing} (${l.margin_pct}%)`).join('; ') + '.'); zh.push(`利润率低于 ${lowPct}%：` + lowM.map(l => `${l.listing}（${l.margin_pct}%）`).join('；') + '。'); }
  if (best.length) { en.push('Most profit: ' + best.map(l => `${l.listing} (${fmt(l.profit)})`).join('; ') + '.'); zh.push('最赚钱：' + best.map(l => `${l.listing}（${fmt(l.profit)}）`).join('；') + '。'); }
  if (missing.length) { en.push(`No cost entered for: ${missing.join('; ')}. Counted as 0, so profit is overstated; add them to the COGS table.`); zh.push(`没有填成本：${missing.join('；')}。这些按 0 计算，利润偏高，请补进 COGS 表。`); }
  const shopParts = sh.month ? [['ads', '广告', sh.ads], ['fees/subscription', '手续费/订阅', sh.etsy_fees], ['shipping labels', '运费标签', sh.shipping_labels], ['taxes', '税', sh.taxes], ['other', '其他', sh.other]].filter(p => Math.abs(p[2] || 0) >= 0.005) : [];
  if (shopParts.length) { en.push(`Costs not tied to a listing in ${latest}: ` + shopParts.map(p => `${p[0]} ${fmt(-p[2])}`).join(', ') + '.'); zh.push(`${latest} 不属于单个 listing 的成本：` + shopParts.map(p => `${p[1]} ${fmt(-p[2])}`).join('，') + '。'); }
}
if (issues.length) { en.push(`${issues.length} reconciliation check(s) need a look (see the Summary output): ${checkCounts}.`); zh.push(`有 ${issues.length} 条对账提示需要看一下（见 Summary 输出）：${checkCounts}。`); }
const rulesSummary = (cfg.summaryLanguage === 'zh' ? zh : en).map(s => '- ' + s).join('\n');

// ---- facts for the AI (aggregates only, no buyer data) ----
const facts = { currency: cur, months: monthly, latest_month: latest || null,
  latest_month_listings: inLatest.map(l => ({ listing: l.listing, units: l.units, income: R(l.revenue + l.shipping_income), profit: l.profit, margin_pct: l.margin_pct,
    cogs: l.cogs, etsy_fees: l.etsy_fees, ads: l.ads, shipping_labels: l.shipping_labels, refunds: l.refunds, flags: l.flags })).slice(0, 40),
  shop_level_costs_latest: sh.month ? { ads: R(sh.ads), fees_and_subscription: R(sh.etsy_fees), other: R(sh.other) } : null,
  data_checks: issues.slice(0, 30) };
const LANGS = { en: 'English', zh: 'Simplified Chinese', de: 'German', fr: 'French', es: 'Spanish', ja: 'Japanese' };
const prompt = `You are a careful bookkeeping assistant for a small Etsy shop. Using ONLY the numbers in the JSON below, write a short monthly profit review in ${LANGS[cfg.summaryLanguage] || 'English'}.
Write 5-8 bullet points (start each with "- "), max 200 words, plain text, no tables:
1. Latest month result (net profit, margin, fee share) and change vs the previous month if present.
2. Which listings lost money or have thin margins, and the main cost driver for each (cogs, shipping labels, Etsy fees, ads, refunds).
3. Data gaps that make the numbers unreliable (missing cost of goods, orders not matched, unknown rows).
4. Two or three concrete things the seller could check next (for example review shipping price vs label cost, Offsite Ads, or pricing of a low-margin listing).
Rules: never invent numbers or listings that are not in the JSON; amounts are in ${cur || 'the shop currency'}; no tax, legal or accounting advice; say "about" when rounding.

JSON:
${JSON.stringify(facts)}`;

return [{ json: { _cfg: cfg, currency: cur, months, monthly, listings, issues, rulesSummary, prompt } }];

const base = $('Compute P&L').first().json;
const r = $input.first().json || {};
const text = (r.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('').trim();
let err = '';
if (r.error || !text) {
  const raw = JSON.stringify(r.error || 'empty reply');
  const m = raw.match(/message\W+([^"\\]{5,160})/);
  const hint = /\b404\b|not found/i.test(raw) ? ' (model not available to this key: change geminiModel in Config)' : /\b(401|403)\b|api key/i.test(raw) ? ' (check the Gemini API key in the credential)' : /\b429\b|quota|rate|spacing your requests/i.test(raw) ? ' (free-tier rate limit or quota: wait and run again)' : /\b(500|503)\b|overloaded|unavailable/i.test(raw) ? ' (Gemini is busy: run again later or pick another Flash model in Config)' : '';
  err = 'AI_ERROR ' + (m ? m[1] : raw).slice(0, 200) + hint + ' -> rule-based summary used instead';
}
return [{ json: { ...base, summary: text || base.rulesSummary, provider: text ? 'gemini' : 'rules (AI failed)', aiError: err } }];

