const d = $input.first().json, at = $now.toFormat('yyyy-LL-dd HH:mm');
const period = d.months.length ? `${d.months[0]}..${d.months[d.months.length - 1]}` : '';
const rows = [{ generated_at: at, period, type: 'summary', item: d.provider, detail: d.summary }];
if (d.aiError) rows.push({ generated_at: at, period, type: 'check', item: 'AI_ERROR', detail: d.aiError });
d.issues.forEach(i => rows.push({ generated_at: at, period, type: 'check', item: i.check, detail: i.detail }));
if (!d.issues.length) rows.push({ generated_at: at, period, type: 'check', item: 'OK', detail: 'No reconciliation problems found' });
return rows.map(json => ({ json }));
